#include "hil/HardwareBenchSessionRunner.h"
#include <filesystem>
#include <fstream>
#include <sstream>
namespace dnxr { namespace { void statsJson(std::ostringstream& os,const char* n,const PercentileStats& s){ os<<"  \""<<n<<"\": {\"p50Ms\": "<<s.p50Ms<<", \"p95Ms\": "<<s.p95Ms<<", \"p99Ms\": "<<s.p99Ms<<", \"maxMs\": "<<s.maxMs<<"}"; } }
std::string HardwareBenchMetrics::toJson() const { std::ostringstream os; os << "{\n  \"release\": \"0.6.5\",\n  \"benchMode\": \"phantom_loopback\",\n  \"humanSubjectAllowed\": false,\n"; statsJson(os,"ackLatency",ackLatency); os<<",\n"; statsJson(os,"commitLatency",commitLatency); os<<",\n"; statsJson(os,"holdLatency",holdLatency); os<<",\n"; statsJson(os,"emergencyLatchLatency",emergencyLatchLatency); os<<",\n"; statsJson(os,"replayWriteLatency",replayWriteLatency); os<<",\n  \"droppedFrameCount\": "<<droppedFrameCount<<",\n  \"ackTimeoutCount\": "<<ackTimeoutCount<<",\n  \"holdFallbackCount\": "<<holdFallbackCount<<",\n  \"transitionCount\": "<<transitionCount<<"\n}\n"; return os.str(); }
HardwareBenchMetrics HardwareBenchSessionRunner::run(std::size_t steps, const BenchDeviceAdapter& adapter) const { HILLatencyHistogram ack,commit,hold,latch,replay; HardwareBenchMetrics m; for(std::size_t i=0;i<steps;++i){ auto s=adapter.sample(i); ack.record(s.ackLatencyMs); commit.record(s.commitLatencyMs); hold.record(s.holdLatencyMs); latch.record(s.emergencyLatchLatencyMs); replay.record(s.replayWriteLatencyMs); if(s.frameDropped) ++m.droppedFrameCount; if(s.ackTimedOut) ++m.ackTimeoutCount; if(s.holdFallback) ++m.holdFallbackCount; ++m.transitionCount; } m.ackLatency=ack.stats(); m.commitLatency=commit.stats(); m.holdLatency=hold.stats(); m.emergencyLatchLatency=latch.stats(); m.replayWriteLatency=replay.stats(); return m; }
bool HardwareBenchSessionRunner::writeMetricsJson(const std::string& path,const HardwareBenchMetrics& metrics) const { std::filesystem::create_directories(std::filesystem::path(path).parent_path()); std::ofstream out(path); if(!out) return false; out<<metrics.toJson(); return true; }
}
